 const reset=()=>setConfirm({title:'شروع دوباره دمو؟',body:'فقط تغییرات همین دمو کنار گذاشته و اطلاعات نمونه برگردانده می‌شوند.',action:()=>{setD(demoSchool());setLife(initialLife());setYearId('y1');setActor('admin');setPage('hub-dashboard');setClassFilter('all');setMajorFilter('all');setGradeFilter('all');setQuery('');setPromotionChoices({})}});
 const filters=<div className="cd-row"><Choice label="فیلتر رشته" value={majorFilter} onChange={setMajorFilter} options={[{value:'all',label:'همه رشته‌ها'},...majorOptions]}/><Choice label="فیلتر پایه" value={gradeFilter} onChange={setGradeFilter} options={[{value:'all',label:'همه پایه‌ها'},...gradeOptions]}/></div>;
 const roster=enrollments.filter(e=>classFilter==='all'||e.classId===classFilter).filter(e=>{const s=d.students.find(s=>s.id===e.studentId)!;return normalize(s.name+' '+s.code+' '+s.father).includes(normalize(query))});

 const profileStudent=modal==='profile'?d.students.find(s=>s.id===form.id):null;
 const tourTitles=teacherId?['ورود به دفتر کلاس','انتخاب کلاس و درس','انتخاب پودمان','جلسه خودکار امروز','حضور و نمره سریع']:isStudent?['داشبورد شخصی','تکلیف و آزمون','نمره‌ها و حضور','پیام به معلم','اعلان و نصب برنامه']:['داشبورد و آمار','دسترسی‌های سمت','پیگیری کارها','اعلان‌ها و پیام‌ها','تنظیمات و امنیت'];
 const tourDescriptions=teacherId?['ثبت حضور و نمره شما را مستقیم به دفتر کلاس می‌برد.','کلاس مطابق برنامه امروز پیشنهاد می‌شود و انتخاب دستی هم در دسترس است.','پودمان فعال را یک‌بار انتخاب کنید تا برای ورود بعدی حفظ شود.','در زمان برنامه، جلسه همان روز خودکار ساخته و شماره‌گذاری می‌شود.','حضور، نمره، مثبت و منفی در همان ردیف ثبت و ویرایش می‌شوند.']:isStudent?['عددها و کارت‌های داشبورد شما را مستقیم به بخش مربوط می‌برند.','تکلیف‌ها، آزمون‌ها و مهلت تحویل در این بخش قرار دارند.','نمره، بازخورد و سابقه حضور خود را یکجا ببینید.','پیام‌های مدرسه و گفت‌وگو با معلم در بخش پیام‌هاست.','با اعلان و نصب وب‌اپ، خبرهای مهم را سریع‌تر دریافت می‌کنید.']:['روی عددها و کارت‌ها بزنید تا فهرست مرتبط باز شود.','منو فقط امکانات مجاز برای سمت شما را نمایش می‌دهد.','امور ارجاع‌شده از کارتابل قابل بررسی و پیگیری است.','پیام‌ها و اعلان‌های جدید از منو و بالای صفحه در دسترس‌اند.','عملیات حساس محدود و در گزارش رویدادهای امنیتی ثبت می‌شود.'];
 return <div className="central-demo"><SidebarProvider dir="rtl"><Toaster dir="rtl" position="top-center"/>{showNotifyPermission&&!showInstall&&<aside className="install-nudge notification-nudge" role="dialog" aria-label="فعال‌سازی اعلان‌ها"><div className="install-nudge-icon"><SchoolIcon size={25}/></div><div className="install-nudge-copy"><b>اعلان‌های مهم مدرسه را فعال کنید</b><p>{'Notification' in window&&Notification.permission==='denied'?'دسترسی قبلاً بسته شده است؛ آن را از تنظیمات سایت در مرورگر مجاز کنید.':'برای پیام‌ها، غیبت‌ها، تکلیف‌ها و اطلاعیه‌های مرتبط با حساب شما اعلان نمایش داده می‌شود.'}</p></div><div className="install-nudge-actions">{'Notification' in window&&Notification.permission!=='denied'&&<button className="btn primary" onClick={()=>void enableNotifications()}>فعال‌کردن اعلان</button>}<button className="btn" onClick={postponeNotifications}>بعداً یادآوری کن</button></div></aside>}{showInstall&&<aside className="install-nudge" role="dialog" aria-label="پیشنهاد نصب دفتر کلاسی"><div className="install-nudge-icon"><Download size={25}/></div><div className="install-nudge-copy"><b>دفتر کلاسی را روی دستگاه نصب کنید</b><p>ورود سریع‌تر، نمایش تمام‌صفحه و دریافت بهتر اعلان‌ها؛ بدون مراجعه دوباره به مرورگر.</p>{installPlatform==='ios'&&<div className="install-steps">در Safari روی <b>اشتراک‌گذاری</b> بزنید، سپس <b>افزودن به صفحه اصلی</b> را انتخاب کنید.</div>}{!installPrompt&&installPlatform==='android'&&<div className="install-steps">از منوی سه‌نقطه مرورگر، «نصب برنامه» یا «افزودن به صفحه اصلی» را بزنید.</div>}{!installPrompt&&installPlatform==='windows'&&<div className="install-steps">از نماد نصب کنار نوار آدرس یا منوی مرورگر، «Install app» را انتخاب کنید.</div>}</div><div className="install-nudge-actions">{installPrompt&&<button className="btn primary" onClick={()=>void installApp()}>نصب برنامه</button>}<button className="btn" onClick={postponeInstall}>بعداً یادآوری کن</button></div></aside>}{tour>=0&&<div className="guided-tour" role="dialog" aria-modal="true"><div className="tour-card"><span className="tour-count">{fa(tour+1)} از ۵</span><h2>{tourTitles[tour]}</h2><p>{tourDescriptions[tour]}</p><div className="cd-row"><button className="btn" onClick={()=>{try{localStorage.setItem('azarmehr-tour-v3:'+actor,'done')}catch{}setTour(-1)}}>دیگر نشان نده</button><span className="cd-grow"/><button className="btn primary" onClick={()=>{if(tour===4){try{localStorage.setItem('azarmehr-tour-v3:'+actor,'done')}catch{}setTour(-1)}else{if(tour===0)go(teacherId?'journal':isStudent?'hub-learning':'hub-dashboard');setTour(tour+1)}}}>{tour===4?'پایان آموزش':'بعدی'}</button></div></div></div>}<Sidebar side="right"><SidebarHeader><div className="brand"><span className="brand-mark"><SchoolIcon/></span><div><b>دفتر کلاسی من</b><small>مدیریت یکپارچه هنرستان</small></div></div></SidebarHeader><SidebarContent>{visibleNav.map(n=><ClosingNavButton key={n.id} className={'nav-item '+(page===n.id?'active':'')} onClick={()=>go(n.id)}><n.icon size={19}/>{n.name}</ClosingNavButton>)}</SidebarContent><SidebarFooter><div className="cd-sidebar-profile"><b>{accounts(d,life).find(p=>p.id===actor)?.name}</b><small>{isStudent?'درس‌ها و فعالیت‌های من':staff?'دسترسی متناسب با سمت':'فقط درس‌های اختصاص‌یافته'}</small></div><small className="credit">طراحی: سعید آذرمهر</small></SidebarFooter></Sidebar><div className="workspace"><header className="topbar"><div className="cd-row"><SidebarTrigger/><b>هنرستان نمونه خادمی</b></div><div className="cd-row topbar-actions"><button className="btn hub-bell" onClick={()=>go('hub-notices')} aria-label="اعلان‌های من">اعلان‌ها <b>{fa(life.notices.filter(n=>n.to===actor&&!n.read).length)}</b></button>{topbarExtra}</div></header><main className="content">{!live&&<section className="cd-demo-toolbar"><div><b>پیش‌نمایش قبل از ساخت نسخه اصلی</b><p>اطلاعات نمونه و موقت‌اند؛ با بازخوانی صفحه پاک می‌شوند. اطلاعات واقعی وارد نکنید.</p></div><Choice label="مشاهده به‌عنوان" value={actor} onChange={v=>{setActor(v);go('hub-dashboard')}} options={actorOptions}/><button className="icon-btn" aria-label="شروع دوباره دمو" onClick={reset}><RotateCcw size={18}/></button></section>}{year.archived&&<div className="hint mb-5">سال بایگانی‌شده · سوابق محفوظ‌اند؛ برای ثبت اطلاعات سال جاری را انتخاب کنید.</div>}<div className="page-heading"><div><span className="cd-muted">{accounts(d,life).find(p=>p.id===actor)?.name}</span><h1>{[...nav,...hubNav].find(n=>n.id===page)?.name}</h1></div><div className="page-heading-actions">{page!=='hub-dashboard'&&<button className="btn dashboard-back" onClick={()=>go('hub-dashboard')}><ArrowRight size={17}/> بازگشت به داشبورد</button>}{['students','subjects','teachers'].includes(page)&&editable&&<button className="btn primary" onClick={()=>open(page==='students'?'student':page==='subjects'?'subject':'teacher',page==='students'?{existing:'new',name:'',father:'',code:'',classId:classFilter==='all'?classes[0]?.id:classFilter}:page==='subjects'?{name:'',gradeId:d.grades[0]?.id,majorId:'all',kind:'general'}:{name:'',email:''})}><Plus size={18}/>{page==='students'?'ثبت دانش‌آموز':page==='subjects'?'درس جدید':'معلم جدید'}</button>}</div></div>
 {page.startsWith('hub-')&&<SchoolHub key={actor+':'+yearId} d={d} l={life} setLife={setLife} actor={actor} yearId={yearId} page={page} go={go} live={!!live} onTaskScore={applyTaskScore}/>} 
 {page==='fields'&&<StudentFields d={d} change={change} readonly={!editable}/>}{page==='overview'&&<div className="stack">{editable&&<section className="cd-notice"><div><h2>ورود یکجای اطلاعات مدرسه</h2><p>کلاس‌ها، معلمان، دانش‌آموزان، درس‌ها، تخصیص تدریس و برنامه هفتگی در یک مرحله ادغام می‌شوند.</p></div><button className="btn primary" disabled={busy} onClick={()=>void loadReadyPackage()}><Upload size={17}/> بازکردن بسته آماده</button></section>}<div className="stats">{[[enrollments.length,'دانش‌آموز یکتا'],[classes.length,'کلاس'],[offers.length,'درس در کلاس‌ها'],[d.teachers.length,'معلم']].map(([v,label])=><div className="stat" key={label}><b>{fa(v)}</b><small>{label}</small></div>)}</div><div className="cd-track-grid">{d.majors.map(m=><section className="panel cd-track" key={m.id}><span className="stat-icon color-0"><GraduationCap/></span><h2>{m.name}</h2><p>{fa(classes.filter(c=>c.majorId===m.id).length)} کلاس · {fa(enrollments.filter(e=>classes.find(c=>c.id===e.classId)?.majorId===m.id).length)} دانش‌آموز</p><div className="cd-row">{d.grades.map(g=><span className="pill" key={g.id}>{g.name}</span>)}</div><button className="btn" onClick={()=>{setMajorFilter(m.id);setGradeFilter('all');setStructureTab('classes');go('structure')}}>کلاس‌های این رشته</button></section>)}</div><section className="panel cd-setup"><h2>مدرسه یک فهرست مشترک دارد</h2><div className="cd-steps">{[['structure','۱. رشته و کلاس'],['students','۲. ثبت دانش‌آموز'],['subjects','۳. برنامه درسی'],['teachers','۴. تعریف معلم'],['assign','۵. تخصیص تدریس']].map(([p,label])=><button key={p} className="btn" onClick={()=>go(p)}>{label}</button>)}</div><p>ثبت دانش‌آموز در کلاس، او را به تمام درس‌های همان کلاس متصل می‌کند؛ ورود دوباره برای هر معلم لازم نیست.</p></section>{offers.some(o=>!o.teacherId)&&<section className="cd-notice"><div><h2>{fa(offers.filter(o=>!o.teacherId).length)} درس هنوز معلم ندارد</h2><p>تا زمان تخصیص، درس در دفتر هیچ معلمی نمایش داده نمی‌شود.</p></div><button className="btn primary" onClick={()=>{setClassFilter('all');setMajorFilter('all');setGradeFilter('all');go('assign')}}>تکمیل تخصیص‌ها</button></section>}</div>}
 {page==='structure'&&<div className="stack"><Tabs value={structureTab} onValueChange={setStructureTab} dir="rtl"><TabsList variant="line"><TabsTrigger value="classes">کلاس‌ها</TabsTrigger><TabsTrigger value="majors">رشته‌ها</TabsTrigger><TabsTrigger value="grades">پایه‌ها</TabsTrigger></TabsList></Tabs><div className="cd-row">{structureTab==='classes'&&filters}<span className="cd-grow"/>{editable&&<button className="btn primary" onClick={()=>open(structureTab==='classes'?'class':structureTab==='majors'?'major':'grade',structureTab==='classes'?{name:'',majorId:d.majors[0]?.id,gradeId:d.grades[0]?.id,section:'۲'}:structureTab==='grades'?{name:'',order:Math.max(...d.grades.map(g=>g.order))+1}:{name:''})}><Plus size={17}/>{structureTab==='classes'?'کلاس جدید':structureTab==='majors'?'رشته جدید':'پایه جدید'}</button>}</div><div className="cd-track-grid">{structureTab==='classes'?filteredClasses.map(c=><section className="panel cd-track" key={c.id}><h2>{c.name}</h2><p>{d.majors.find(m=>m.id===c.majorId)?.name} · {gradeName(d,c.gradeId)}</p><p>{fa(enrollments.filter(e=>e.classId===c.id).length)} دانش‌آموز · {fa(offers.filter(o=>o.classId===c.id).length)} درس</p><div className="cd-row"><button className="btn" onClick={()=>{setClassFilter(c.id);go('students')}}>دانش‌آموزان</button><button className="btn" onClick={()=>{setClassFilter(c.id);setMajorFilter('all');setGradeFilter('all');go('assign')}}>درس و معلم</button>{editable&&<button className="icon-btn" aria-label={'ویرایش کلاس '+c.name} onClick={()=>open('class',c)}><Pencil size={17}/></button>}</div></section>):(structureTab==='majors'?d.majors:d.grades).map(item=><section className="panel cd-track" key={item.id}><h2>{item.name}</h2>{'order'in item&&<p>ترتیب آموزشی: {fa(Number(item.order))}</p>}{editable&&<button className="btn" onClick={()=>open(structureTab==='majors'?'major':'grade',item)}>ویرایش</button>}</section>)}</div></div>}
 {page==='students'&&<section className="panel"><div className="toolbar"><input className="cd-search" aria-label="جست‌وجوی دانش‌آموزان مدرسه" value={query} onChange={e=>setQuery(e.target.value)} placeholder="نام، نام پدر یا کد…"/><Choice label="کلاس دانش‌آموزان" value={classFilter} onChange={setClassFilter} options={[{value:'all',label:'همه کلاس‌ها'},...classOptions]}/>{editable&&<button className="btn" disabled={!classes.length} onClick={()=>open('import',{classId:classFilter==='all'?classes[0]?.id:classFilter})}><Upload size={17}/> اکسل / فایل سیدا</button>}<button className="btn" onClick={()=>void safe(async()=>{await exportExcel('فهرست مدرسه',[['نام و نام خانوادگی','نام پدر','کد دانش‌آموزی','کلاس','رشته','پایه','شماره همراه',...(d.customFields||[]).map(f=>f.name)],...roster.map(e=>{const s=d.students.find(s=>s.id===e.studentId)!,c=classes.find(c=>c.id===e.classId)!;return [s.name,s.father,s.code,c.name,d.majors.find(m=>m.id===c.majorId)?.name||'',gradeName(d,c.gradeId),s.phone||'',...(d.customFields||[]).map(f=>f.type==='date'&&s.extra?.[f.id]?jalali(s.extra[f.id]):s.extra?.[f.id]||'')]})])})}><Download size={17}/> اکسل</button></div><Table><TableHeader><TableRow>{['دانش‌آموز','نام پدر','کلاس / پایه و رشته','درس‌ها','عملیات'].map(x=><TableHead key={x}>{x}</TableHead>)}</TableRow></TableHeader><TableBody>{roster.map(e=>{const s=d.students.find(s=>s.id===e.studentId)!,c=classes.find(c=>c.id===e.classId)!;return <TableRow key={e.id}><TableCell><button className="cd-student-name" onClick={()=>open('profile',{id:s.id})}>{s.name}</button>{s.incomplete&&<span className="pill" title={(s.missingFields||[]).join('، ')}>نیازمند تکمیل</span>}<small>{s.code}</small></TableCell><TableCell>{s.father}</TableCell><TableCell>{c.name}<small>{gradeName(d,c.gradeId)} · {d.majors.find(m=>m.id===c.majorId)?.name}</small></TableCell><TableCell>{fa(offers.filter(o=>o.classId===c.id).length)} درس خودکار</TableCell><TableCell><button className="btn compact" onClick={()=>open('profile',{id:s.id})}>پرونده</button>{editable&&<button className="icon-btn" aria-label={'ویرایش دانش‌آموز '+s.name+' '+s.code} onClick={()=>open('student',{...s,classId:e.classId})}><Pencil size={16}/></button>}</TableCell></TableRow>})}</TableBody></Table>{!roster.length&&<Empty text="دانش‌آموزی با این فیلتر پیدا نشد"/>}</section>}
 {page==='subjects'&&<div className="stack">{filters}<p className="hint">درس عمومی می‌تواند به همه رشته‌های یک پایه تعلق داشته باشد؛ درس تخصصی به رشته و پایه مشخص تعلق دارد. این فهرست نمونه است و برنامه مصوب هنرستان را مدیر تنظیم می‌کند.</p><section className="panel"><Table><TableHeader><TableRow>{['درس','نوع','پایه','رشته','کلاس‌های این سال',''].map((x,i)=><TableHead key={i}>{x}</TableHead>)}</TableRow></TableHeader><TableBody>{d.subjects.filter(s=>(gradeFilter==='all'||s.gradeId===gradeFilter)&&(majorFilter==='all'||s.majorId==='all'||s.majorId===majorFilter)).map(s=><TableRow key={s.id}><TableCell>{s.name}</TableCell><TableCell><span className="pill">{s.kind==='general'?'عمومی':'تخصصی'}</span></TableCell><TableCell>{gradeName(d,s.gradeId)}</TableCell><TableCell>{s.majorId==='all'?'همه رشته‌ها':d.majors.find(m=>m.id===s.majorId)?.name}</TableCell><TableCell>{fa(offers.filter(o=>o.subjectId===s.id).length)}</TableCell><TableCell>{editable&&<button className="icon-btn" aria-label={'ویرایش درس '+s.name} onClick={()=>open('subject',s)}><Pencil size={16}/></button>}</TableCell></TableRow>)}</TableBody></Table></section></div>}
 {page==='teachers'&&<div className="cd-track-grid">{d.teachers.map(t=><section className="panel cd-track" key={t.id}><span className="avatar">{t.name[0]}</span><h2>{t.name}</h2>{t.incomplete&&<span className="pill" title={(t.missingFields||[]).join('، ')}>نیازمند تکمیل</span>}<p dir="ltr">{t.email||'ایمیل ثبت نشده'}</p><p>{t.phone||'شماره همراه ثبت نشده'}</p><small>کد ملی: {t.nationalCode||'ثبت نشده'} · کد پرسنلی: {t.personnelCode||'ثبت نشده'}</small><p>{fa(offers.filter(o=>o.teacherId===t.id).length)} درس در {fa(new Set(offers.filter(o=>o.teacherId===t.id).map(o=>o.classId)).size)} کلاس</p><button className="btn primary" onClick={()=>{setActor('teacher:'+t.id);go('journal')}}>دیدن پنل این معلم</button><div className="cd-row"><button className="btn" onClick={()=>{setClassFilter('all');setMajorFilter('all');setGradeFilter('all');go('assign')}}>تخصیص درس</button>{editable&&<button className="icon-btn" aria-label={'ویرایش معلم '+t.name} onClick={()=>open('teacher',t)}><Pencil size={17}/></button>}</div></section>)}</div>}
 {page==='assign'&&<div className="stack"><div className="cd-row">{filters}<Choice label="کلاس تخصیص" value={classFilter} onChange={setClassFilter} options={[{value:'all',label:'همه کلاس‌ها'},...classOptions]}/></div><p className="hint">هر ردیف یک درس در یک کلاس است. مدیر در همین جدول مشخص می‌کند درس پودمانی است یا ارزشیابی سالانه دارد. تغییر معلم یا شیوه ارزشیابی، دانش‌آموزان و سوابق قبلی را حذف نمی‌کند.</p><section className="panel"><Table><TableHeader><TableRow>{['کلاس','درس','نوع درس','شیوه ارزشیابی','معلم مسئول'].map(x=><TableHead key={x}>{x}</TableHead>)}</TableRow></TableHeader><TableBody>{filteredOffers.map(o=><TableRow key={o.id}><TableCell>{classes.find(c=>c.id===o.classId)?.name}</TableCell><TableCell>{o.name}</TableCell><TableCell>{d.subjects.find(s=>s.id===o.subjectId)?.kind==='general'?'عمومی':'تخصصی'}</TableCell><TableCell><Choice disabled={!editable} label={'شیوه ارزشیابی '+o.name} value={o.gradingMode||'modular'} onChange={v=>{change(n=>{n.offerings.find(x=>x.id===o.id)!.gradingMode=v as 'modular'|'annual'});toast.success('شیوه ارزشیابی ثبت شد')}} options={[{value:'modular',label:'پودمانی؛ ۵ پودمان'},{value:'annual',label:'غیرپودمانی؛ سالانه'}]}/></TableCell><TableCell><Choice disabled={!editable} label={'معلم '+o.name+' '+classes.find(c=>c.id===o.classId)?.name} value={o.teacherId||'none'} onChange={v=>{change(n=>{n.offerings.find(x=>x.id===o.id)!.teacherId=v==='none'?'':v});toast.success(live?'تخصیص ثبت شد':'تخصیص در دمو اعمال شد')}} options={[{value:'none',label:'بدون معلم'},...d.teachers.filter(t=>t.active).map(t=>({value:t.id,label:t.name}))]}/></TableCell></TableRow>)}</TableBody></Table></section></div>}
 {['journal','finals','reports'].includes(page)&&<CentralDesk key={actor+':'+yearId} data={selectedData} page={page} onPage={go} readOnly={staff||year.archived} onChange={applyTeacher} onIncident={reportIncident}/>}
 {page==='office'&&staff&&<CentralOffice key={yearId} d={d} yearId={yearId} readonly={year.archived} change={change} onIncident={r=>open('incident',r)}/>}
 {page==='promotion'&&staff&&<div className="stack"><section className="panel cd-setup"><h2>ابتدا بررسی، سپس انتقال سال</h2><p>سوابق سال فعلی بایگانی می‌شوند. پیش‌فرض: دهم به یازدهم و یازدهم به دوازدهم در همان رشته. برای هر دانش‌آموز می‌توانید تکرار پایه یا عدم انتقال را انتخاب کنید. خروج از پایه آخر، تأیید رسمی فراغت از تحصیل نیست.</p><Field label="سال تحصیلی مقصد"><input disabled={!editable} value={nextYear} onChange={e=>setNextYear(e.target.value)}/></Field><p>کلاس‌ها و برنامه درسی سال مقصد ساخته می‌شوند؛ تخصیص معلم در سال جدید دوباره انجام می‌شود.</p><button className="btn primary" disabled={!editable||!enrollments.length} onClick={()=>{setError('');setConfirm({title:live?'انتقال سال تحصیلی اجرا شود؟':'اجرای انتقال فقط در دمو؟',body:'سال فعلی بایگانی و ثبت‌نام‌های سال مقصد طبق انتخاب‌های جدول ایجاد می‌شوند. نمرات و حضورهای قبلی در سال قبل باقی می‌مانند.',action:()=>{try{const n=structuredClone(d);const id=promote(n,yearId,nextYear,promotionChoices);setD(n);setYearId(id);setClassFilter('all');setPromotionChoices({});go('overview');toast.success(live?'سال جدید ساخته و سال قبلی بایگانی شد':'سال جدید در دمو ساخته شد')}catch(e){setError((e as Error).message)}}})}}>{live?'اجرای انتقال سال':'اجرای آزمایشی انتقال سال'}</button>{error&&<div className="error">{error}</div>}</section><section className="panel"><Table><TableHeader><TableRow>{['دانش‌آموز','کلاس فعلی','تصمیم','مقصد پیش‌نمایش'].map(x=><TableHead key={x}>{x}</TableHead>)}</TableRow></TableHeader><TableBody>{enrollments.map(e=>{const s=d.students.find(s=>s.id===e.studentId)!,c=classes.find(c=>c.id===e.classId)!,gs=[...d.grades].sort((a,b)=>a.order-b.order),next=gs[gs.findIndex(g=>g.id===c.gradeId)+1],mode=promotionChoices[e.id]||'advance';return <TableRow key={e.id}><TableCell>{s.name}<small>{s.code}</small></TableCell><TableCell>{c.name}</TableCell><TableCell><Choice disabled={!editable} label={'تصمیم انتقال '+s.code} value={mode} onChange={v=>setPromotionChoices(p=>({...p,[e.id]:v}))} options={[{value:'advance',label:next?'ارتقای پایه':'خروج از پایه آخر'},{value:'repeat',label:'تکرار پایه'},{value:'skip',label:'فعلاً انتقال نده'}]}/></TableCell><TableCell>{mode==='skip'?'بدون ثبت‌نام در سال مقصد':mode==='repeat'?c.name:next?next.name+' '+d.majors.find(m=>m.id===c.majorId)?.name+' / '+c.section:'خروج از دوره؛ سوابق محفوظ'}</TableCell></TableRow>})}</TableBody></Table></section></div>}
 {page==='appearance'&&<section className="panel cd-setup"><h2>ظاهر دلخواه شما</h2><p>انتخاب تم فقط ظاهر را تغییر می‌دهد و در همین مرورگر می‌ماند.</p><div className="cd-theme-grid">{[['blue','آبی روشن','سبک و شبیه ابزارهای گوگل'],['green','سبز مدرسه','روشن با تأکید سبز'],['dark','تیره','پس‌زمینه تیره با کنتراست خوانا']].map(([id,name,desc])=><button key={id} className={'cd-theme '+(theme===id?'selected':'')} aria-pressed={theme===id} onClick={()=>setTheme(id)}><span className={'cd-theme-preview '+id}><i/><i/><i/></span><b>{name}</b><p>{desc}</p>{theme===id&&<span>✓ انتخاب‌شده</span>}</button>)}</div></section>}
 </main></div><Dialog open={!!modal} onOpenChange={v=>{if(!v)setModal('')}}><DialogContent dir="rtl" className={'app-dialog cd-modal '+(['profile','import','school-import'].includes(modal)?'wide-dialog':'')}><DialogTitle>{{major:'رشته',grade:'پایه',class:'کلاس',student:'پرونده و ثبت‌نام دانش‌آموز',subject:'تعریف درس',teacher:'مشخصات معلم',profile:'پرونده یکپارچه دانش‌آموز',import:'ورود دانش‌آموزان مدرسه','school-import':'ورود یکجای اطلاعات مدرسه',incident:'گزارش انضباطی'}[modal]||''}</DialogTitle><DialogDescription>{modal==='profile'?'یک پرونده، یک ثبت‌نام در هر سال و تمام سوابق درس‌ها.':modal==='school-import'?'پیش از ورود، تعداد رکوردهای بسته را بررسی کنید.':live?'تغییرات در پایگاه داده مدرسه ثبت می‌شوند.':'تغییرات این صفحه فقط در دمو اعمال می‌شوند.'}</DialogDescription>{error&&<div role="alert" className="error">{error}</div>}
 {!['profile','import','school-import'].includes(modal)&&<form className="stack" onSubmit={e=>{e.preventDefault();save()}}>
 {['major','grade','class','subject','teacher'].includes(modal)&&<Field label={modal==='teacher'?'نام و نام خانوادگی':'نام'}><input value={form.name||''} required maxLength={150} onChange={e=>patch('name',e.target.value)}/></Field>}
 {modal==='grade'&&<Field label="ترتیب پایه"><input type="number" min={1} required value={form.order} onChange={e=>patch('order',e.target.value)}/></Field>}
 {modal==='class'&&<><Field label="رشته"><Choice disabled={!!form.id} label="رشته کلاس" value={form.majorId} onChange={v=>patch('majorId',v)} options={majorOptions}/></Field><Field label="پایه"><Choice disabled={!!form.id} label="پایه کلاس" value={form.gradeId} onChange={v=>patch('gradeId',v)} options={gradeOptions}/></Field><Field label="شماره / شعبه کلاس"><input disabled={!!form.id} required value={form.section} onChange={e=>patch('section',e.target.value)}/></Field><p>رشته و پایه، مبنای برنامه درسی هستند؛ برای ترکیب متفاوت کلاس جدید بسازید.</p></>}
 {modal==='student'&&<>{!form.id&&<Field label="نوع ثبت‌نام"><Choice label="نوع ثبت‌نام" value={form.existing||'new'} onChange={v=>{const s=d.students.find(s=>s.id===v);setForm((f:any)=>({...f,existing:v,name:s?.name||'',father:s?.father||'',code:s?.code||''}))}} options={[{value:'new',label:'دانش‌آموز جدید'},...d.students.filter(s=>!d.enrollments.some(e=>e.studentId===s.id&&e.yearId===yearId)).map(s=>({value:s.id,label:s.name+' · '+s.code}))]}/></Field>}<div className="form-grid"><Field label="نام"><input maxLength={80} value={form.firstName||''} onChange={e=>patch('firstName',e.target.value)}/></Field><Field label="نام خانوادگی"><input maxLength={100} value={form.lastName||''} onChange={e=>patch('lastName',e.target.value)}/></Field></div><Field label="نام کامل (برای داده‌های قدیمی)"><input required maxLength={150} value={form.name||''} onChange={e=>patch('name',e.target.value)}/></Field><Field label="شماره همراه دانش‌آموز (اختیاری)"><input inputMode="tel" value={form.phone||''} onChange={e=>patch('phone',e.target.value)}/></Field><Field label="نام پدر (قابل تکمیل در آینده)"><input maxLength={100} value={form.father||''} onChange={e=>patch('father',e.target.value)}/></Field><Field label="کد دانش‌آموزی (قابل تکمیل در آینده)"><input maxLength={40} value={form.code||''} onChange={e=>patch('code',e.target.value)}/></Field><Field label="کد ملی دانش‌آموز (اولویت نام کاربری)"><input inputMode="numeric" maxLength={10} value={form.nationalCode||''} onChange={e=>patch('nationalCode',e.target.value)}/></Field><Field label="کلاس مقصد"><Choice label="کلاس مقصد" value={form.classId||''} onChange={v=>patch('classId',v)} options={classOptions}/></Field>{(d.customFields||[]).map(field=><Field key={field.id} label={field.name+(field.required?' (الزامی)':'')} >{field.type==='date'?<JalaliDate value={form.extra?.[field.id]||''} onChange={v=>patch('extra',{...form.extra,[field.id]:v})} clearable={!field.required} label={field.name}/>:<input required={field.required&&!!form.markComplete} inputMode={field.type==='number'?'decimal':'text'} maxLength={2000} value={form.extra?.[field.id]||''} onChange={e=>patch('extra',{...form.extra,[field.id]:e.target.value})}/>}</Field>)}<p className="hint">پایه و رشته از کلاس انتخاب‌شده مشخص می‌شوند. این دانش‌آموز به تمام درس‌های همان کلاس متصل می‌شود.</p>{form.incomplete&&<label className="cd-row"><input type="checkbox" checked={!!form.markComplete} onChange={e=>patch('markComplete',e.target.checked)}/> نام کامل بررسی و تأیید شده است</label>}</>}
 {modal==='subject'&&<><Field label="نوع درس"><Choice disabled={!!form.id} label="نوع درس" value={form.kind} onChange={v=>{patch('kind',v);if(v==='technical'&&form.majorId==='all')patch('majorId',d.majors[0]?.id)}} options={[{value:'general',label:'عمومی'},{value:'technical',label:'تخصصی'}]}/></Field><Field label="پایه"><Choice disabled={!!form.id} label="پایه درس" value={form.gradeId} onChange={v=>patch('gradeId',v)} options={gradeOptions}/></Field><Field label="رشته"><Choice disabled={!!form.id} label="رشته درس" value={form.majorId} onChange={v=>patch('majorId',v)} options={[...(form.kind==='general'?[{value:'all',label:'همه رشته‌ها'}]:[]),...majorOptions]}/></Field><p>درس جدید به تمام کلاس‌های سازگار همین سال اضافه می‌شود. سپس معلم هر کلاس را از تخصیص تدریس انتخاب کنید.</p></>}
 {modal==='teacher'&&<><Field label="شماره همراه معلم (قابل تکمیل در آینده)"><input inputMode="tel" value={form.phone||''} onChange={e=>patch('phone',e.target.value)}/></Field><Field label="کد ملی"><input inputMode="numeric" maxLength={10} value={form.nationalCode||''} onChange={e=>patch('nationalCode',e.target.value)}/></Field><Field label="کد پرسنلی"><input inputMode="numeric" maxLength={20} value={form.personnelCode||''} onChange={e=>patch('personnelCode',e.target.value)}/></Field><Field label="ایمیل (اختیاری)"><input type="email" value={form.email||''} onChange={e=>patch('email',e.target.value)}/></Field><p>{live?'پس از ذخیره پرونده، از «حساب‌های ورود» برای معلم حساب ایجاد کنید.':'در دمو از «مشاهده به‌عنوان» پنل معلم را بررسی کنید.'}</p></>}
 {modal==='incident'&&<><h3>{d.students.find(s=>s.id===form.studentId)?.name}</h3><Field label="تاریخ"><JalaliDate value={form.date} onChange={v=>patch('date',v)} label="تاریخ گزارش"/></Field><Field label="موضوع"><input required maxLength={150} value={form.title} onChange={e=>patch('title',e.target.value)}/></Field><Field label="شرح"><textarea required maxLength={2000} value={form.detail} onChange={e=>patch('detail',e.target.value)}/></Field>{staff&&<><Field label="وضعیت رسیدگی"><Choice label="وضعیت رسیدگی" value={form.status} onChange={v=>patch('status',v)} options={[{value:'open',label:'باز'},{value:'in_progress',label:'در حال پیگیری'},{value:'resolved',label:'رسیدگی‌شده'}]}/></Field><Field label="نتیجه پیگیری"><textarea maxLength={2000} value={form.followup} onChange={e=>patch('followup',e.target.value)}/></Field></>}<p>گزارش انضباطی، نمره انضباط را تغییر نمی‌دهد.</p></>}
 <button className="btn primary" type="submit">{live?'ثبت اطلاعات':'اعمال در دمو'}</button></form>}
 {modal==='profile'&&profileStudent&&<div className="stack"><h2>{profileStudent.name}</h2><p>نام پدر: {profileStudent.father||'ثبت نشده'} · کد: {profileStudent.code}</p><p>شماره همراه: {profileStudent.phone||'ثبت نشده'}</p>{profileStudent.incomplete&&<p><span className="pill">نیازمند تکمیل</span> {(profileStudent.missingFields||[]).join('، ')}</p>}<div className="cd-track-grid">{(d.customFields||[]).map(f=><div className="hint" key={f.id}><b>{f.name}</b><p>{f.type==='date'&&profileStudent.extra?.[f.id]?jalali(profileStudent.extra[f.id]):profileStudent.extra?.[f.id]||'ثبت نشده'}</p></div>)}</div><h3>ثبت‌نام‌ها و سابقه سال تحصیلی</h3>{d.enrollments.filter(e=>e.studentId===profileStudent.id).map(e=><div className="hint" key={e.id}>{d.years.find(y=>y.id===e.yearId)?.name} · {e.status==='graduated'?'خروج از دوره':d.classes.find(c=>c.id===e.classId)?.name}</div>)}<h3>درس‌های سال انتخاب‌شده</h3>{offers.filter(o=>enrollments.some(e=>e.studentId===profileStudent.id&&e.classId===o.classId)).map(o=><div className="cd-row" key={o.id}><b>{o.name}</b><span className="cd-grow"/><span>{d.teachers.find(t=>t.id===o.teacherId)?.name||'بدون معلم'}</span></div>)}<h3>سوابق جلسات (تمام سال‌ها)</h3>{d.sessions.filter(s=>s.records[profileStudent.id]).map(s=><div className="history-row" key={s.id}><b>{jalali(s.date)} · {d.offerings.find(o=>o.id===s.courseId)?.name}</b><p>{s.title} · {({present:'حاضر',absent:'غایب',late:'تأخیر',excused:'موجه',unset:'ثبت‌نشده'} as Record<string,string>)[s.records[profileStudent.id].attendance]}</p><p>{s.records[profileStudent.id].marks.map(m=>m.type+': '+markLabel(m)).join(' · ')}</p></div>)}<button className="btn" onClick={()=>window.print()}>چاپ پرونده</button></div>}
 {modal==='school-import'&&<div className="stack"><div className="hint"><b>پیش‌نمایش بسته {bulkPackage?.year}</b><p>{fa(bulkPackage?.classes.length||0)} کلاس · {fa(bulkPackage?.students.length||0)} دانش‌آموز · {fa(bulkPackage?.teachers.length||0)} معلم · {fa(bulkPackage?.assignments.length||0)} تخصیص درس · {fa(bulkPackage?.schedules?.length||0)} بازه برنامه هفتگی</p></div><p>اجرای دوباره این بسته رکورد تکراری نمی‌سازد. حساب ورود برای معلمان و دانش‌آموزان ساخته نمی‌شود و اطلاعات فعلی، نمره‌ها و حضورها حذف نخواهند شد.</p><p><span className="pill">نیازمند تکمیل</span> کنار پرونده‌هایی نمایش داده می‌شود که شماره همراه، نام کامل، نام پدر یا کد دانش‌آموزی ندارند.</p><input aria-label="انتخاب بسته ورود مدرسه" type="file" accept=".json" onChange={e=>{const file=e.target.files?.[0];if(file)void safe(async()=>setBulkPackage(validateSchoolPackage(JSON.parse(await file.text()))))}}/><button className="btn primary" disabled={!bulkPackage||busy} onClick={applyBulkImport}>ورود همه اطلاعات در یک مرحله</button></div>}
{modal==='import'&&<div className="stack"><p>یک فایل برای فهرست مرکزی مدرسه. مشخصات دلخواه با تطبیق دقیق عنوان ستون، همراه نام پدر، کد و شماره همراه وارد می‌شوند. هر بار یک کلاس مقصد انتخاب کنید.</p><Field label="کلاس مقصد"><Choice label="کلاس ورود فایل" value={form.classId||''} onChange={v=>patch('classId',v)} options={classOptions}/></Field><input aria-label="فایل دانش‌آموزان" type="file" accept=".xlsx,.xls,.csv" onChange={e=>{const f=e.target.files?.[0];if(f)void safe(async()=>{const data=await readExcel(f);setSheets(data);setSheet('0');setHeader(0);const h=data[0]?.rows[0]||[];setMapping({name:String(Math.max(0,headerGuess(h,'name'))),father:String(Math.max(0,h.findIndex(x=>normalize(x).includes('پدر')))),code:String(Math.max(0,headerGuess(h,'code')))})})}}/>{sheets.length>0&&<><Field label="برگه"><Choice label="برگه فایل" value={sheet} onChange={setSheet} options={sheets.map((s,i)=>({value:String(i),label:s.name}))}/></Field><Field label="ردیف عنوان ستون‌ها"><input type="number" min={1} max={50} value={header+1} onChange={e=>setHeader(Math.max(0,Math.min(49,Number(e.target.value)-1)))}/></Field>{(['name','father','code'] as const).map(k=><Field key={k} label={{name:'نام و نام خانوادگی',father:'نام پدر',code:'کد دانش‌آموزی'}[k]}><Choice label={'ستون '+k} value={mapping[k]} onChange={v=>setMapping(p=>({...p,[k]:v}))} options={head.map((x,i)=>({value:String(i),label:`${i+1} · ${x||'بدون عنوان'}`}))}/></Field>)}<p>{fa(importRows.length)} قابل ورود · {fa(duplicates)} کد موجود یا تکراری · {fa(invalid)} ناقص</p><Table><TableHeader><TableRow><TableHead>نام</TableHead><TableHead>نام پدر</TableHead><TableHead>کد</TableHead></TableRow></TableHeader><TableBody>{importRows.slice(0,5).map(s=><TableRow key={s.code}><TableCell>{s.name}</TableCell><TableCell>{s.father}</TableCell><TableCell>{s.code}</TableCell></TableRow>)}</TableBody></Table><button disabled={!importRows.length||busy} className="btn primary" onClick={()=>{if(new Set(Object.values(mapping)).size!==3){setError('سه ستون متفاوت انتخاب کنید');return}if(!form.classId||importRows.length>2000){setError('کلاس لازم است و حداکثر ۲۰۰۰ دانش‌آموز در هر بار مجاز است');return}change(n=>{for(const item of importRows){const id=uid();n.students.push({...item,id});n.enrollments.push({id:uid(),yearId,studentId:id,classId:form.classId,status:'active'})}});setModal('');toast.success('فهرست مرکزی تکمیل شد')}}>ورود به کلاس انتخاب‌شده</button></>}<button className="btn" onClick={()=>void safe(async()=>{await exportExcel('الگوی ثبت‌نام مدرسه',[['نام و نام خانوادگی','نام پدر','کد دانش‌آموزی','شماره همراه',...(d.customFields||[]).map(f=>f.name)],['دانش‌آموز نمونه','علی','001234','',...(d.customFields||[]).map(()=> '')]])})}>دریافت الگوی اکسل</button></div>}
 </DialogContent></Dialog><AlertDialog open={!!confirm} onOpenChange={v=>{if(!v)setConfirm(null)}}><AlertDialogContent dir="rtl"><AlertDialogHeader><AlertDialogTitle>{confirm?.title}</AlertDialogTitle><AlertDialogDescription>{confirm?.body}</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>انصراف</AlertDialogCancel><AlertDialogAction onClick={()=>{confirm.action();setConfirm(null)}}>تأیید در دمو</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></SidebarProvider></div>
